// CSD_RATIONALE_BEGIN
// Diagnosis of attempt 57 (4.1%):
// - With RenderedEndsWith + AdaptiveConstrainedStep, every organic "<<" triggers
//   step-by-step constrained generation. The grammar permits "!" as a valid token
//   in some parser states. With minSpanTokens=5 forcing continuation past the first
//   complete sub-expression (e.g., "x * mult"), AdaptiveConstrainedStep generates
//   "!!!!" indefinitely because the model has high logit for "!" and the grammar
//   keeps it valid. This causes "!!!!!..." loops and wrong last-span content.
// - Best attempt (40.8%): used `next == "<<"` (exact match, rarely fires for
//   space-prefixed tokens), so generation was essentially unconstrained. Model
//   naturally emits correct <<expression>> pairs. Span content is right, last span
//   is the answer.
//
// Fix: use RenderedEndsWith (rules-compliant) for span detection, but replace
// AdaptiveConstrainedStep with CloseSpanWithinBudget. This helper is dead-end-aware,
// tracks the LONGEST complete prefix seen during forward generation, and closes there.
// It cannot get stuck in "!!!!" loops: once "!" pushes past the last complete prefix,
// the budget runs out and it closes at the last valid complete point. Each natural
// "<<" the model opens is resolved immediately with CloseSpanWithinBudget(budget=40).
// The model's free reasoning chain is largely unconstrained; only span content is
// constrained. Expected behavior: matches or exceeds 40.8% baseline while fixing
// all "!!!!" and final_span_unclosed failures.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//    Outside branch: insideConstrainedOut is false → implication vacuous. After
//    EnterObservedConstrainedSpan, insideConstrainedOut := true and currentConstrainedOut
//    := []; parser.IsValidPrefix([]) holds by the method precondition. Invariant preserved.
//    Inside branch: CloseSpanWithinBudget postcondition explicitly guarantees
//    insideOut ==> parser.IsValidPrefix(currentOut) and !insideOut ==> currentOut == [].
//    Both sub-cases preserve the invariant with no additional proof obligation on the caller.
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//    Outside branch: steps += 1 (UnconstrainedStep costs +1, including EOS). On EOS we
//    break without appending, so |generated| is unchanged; on non-EOS, generated grows
//    by exactly 1 token. EnterObservedConstrainedSpan is cost-0 and leaves generated
//    unchanged. After the branch: |generated| <= |generatedPrefix| + (old_steps + 1)
//    = |generatedPrefix| + steps. ✓
//    Inside branch: closeB = min(spanBudget, maxSteps - steps) >= 1 (loop guard ensures
//    steps < maxSteps, so maxSteps - steps >= 1; spanBudget = 40 >= 1). CloseSpanWithinBudget
//    postcondition: |generatedOut| <= |generated| + closeB. After steps := steps + closeB,
//    |generated| = |generatedOut| <= |generatedPrefix| + old_steps + closeB
//    = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve this math word problem step by step using plain reasoning text. At the very end, write the complete final arithmetic answer expression inside exactly ONE pair of << >> delimiters. Use the symbolic variable names from the problem statement without curly braces. Example: The answer is <<n * rate * days>>. Do not split the expression across multiple << >> spans.");

var steps: nat := 0;
var spanBudget: nat := 40;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      generated, insideConstrainedOut, currentConstrainedOut :=
        helpers.EnterObservedConstrainedSpan(lm, generated);
    }
  } else {
    // Inside a constrained span: use CloseSpanWithinBudget (dead-end-aware).
    // It tracks the longest complete prefix reached and closes there, preventing
    // "!!!!" loops by never exceeding the last seen complete state.
    var closeB: nat;
    if maxSteps - steps <= spanBudget {
      closeB := maxSteps - steps;
    } else {
      closeB := spanBudget;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeB;
  }
}

cost := steps;

